def mobius_transform(f):
    n = int(math.log2(len(f)))
    for k in range(1, n + 1):
        sign = (-1) ** (k % 2)
        for i in range(n - k + 1):
            f[i] += sign * f[i + k]
    return f

def gaussian_elimination(A):
    m, n = len(A), len(A[0])
